<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Register</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body>
<div class='page' style='max-width:500px;margin-top:8vh'><div class='glass-card'><h2><i class='fa-solid fa-user-plus'></i> New Commander</h2><p class='sub'>Create your nation-bound account.</p><input id='username' class='search' placeholder='Username'><br><br><input id='email' class='search' placeholder='Email'><br><br><input id='password' type='password' class='search' placeholder='Password'><br><br><button id='btn' class='btn' style='width:100%'>Register</button><p id='msg' class='sub'></p><p class='sub'>Already have account? <a href='/login'>Login</a></p></div></div>
<script>
btn.onclick=async()=>{try{const r=await fetch('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,email:email.value,password:password.value})});const j=await r.json();if(j.error)throw new Error(j.message||j.error);location.href='/dashboard';}catch(e){msg.textContent=e.message;msg.style.color='#ef4444';}};
</script></body></html>
